// src/components/DcsSurvey.jsx
import React, { useState } from "react";
import { DCS_QUESTIONS, DCS_OPTIONS, DCS_CITATION } from "../constants/dcs";

const DcsSurvey = ({ onComplete, onClose }) => {
  const [currentDcsIndex, setCurrentDcsIndex] = useState(0);
  const [dcsAnswers, setDcsAnswers] = useState({});

  const handleDcsSelect = (value) => {
    const currentQuestion = DCS_QUESTIONS[currentDcsIndex];
    const updatedAnswers = { ...dcsAnswers, [currentQuestion.id]: value };
    setDcsAnswers(updatedAnswers);

    if (currentDcsIndex < DCS_QUESTIONS.length - 1) {
      setCurrentDcsIndex(currentDcsIndex + 1);
    } else {
      // 16 題全部答完，將結果回傳給父組件
      onComplete(updatedAnswers);
    }
  };

  return (
    <div style={containerBoundedOverlayStyle}>
      <div style={contentStyle}>
        {/* 頂部關閉按鈕 (若允許中途退出) */}
        <div style={{ width: "100%", display: "flex", justifyContent: "end" }}>
          <button
            onClick={onClose}
            style={{
              background: "none",
              border: "none",
              fontSize: "1.1rem",
              cursor: "pointer",
              color: "#ccc",
            }}
          >
            ✕
          </button>
        </div>

        {/* 學術引用宣告 */}
        <div style={citationHeaderStyle}>
          <span style={{ fontWeight: "600" }}>{DCS_CITATION.title}</span>
          <small
            style={{
              color: "#a0a0a0",
              display: "block",
              fontSize: "0.7rem",
              marginTop: "4px",
              fontWeight: "400",
            }}
          >
            {DCS_CITATION.source}
          </small>
        </div>

        {/* 進度條 */}
        <div style={progressContainerStyle}>
          <div style={progressBarBgStyle}>
            <div
              style={{
                ...progressFillStyle,
                width: `${((currentDcsIndex + 1) / DCS_QUESTIONS.length) * 100}%`,
              }}
            ></div>
          </div>
          <span
            style={{
              fontSize: "0.85rem",
              color: "#666",
              minWidth: "70px",
              textAlign: "right",
            }}
          >
            進度：{currentDcsIndex + 1} / {DCS_QUESTIONS.length}
          </span>
        </div>

        {/* 題目核心區 */}
        <div style={questionZoneStyle}>
          <p
            style={{
              fontSize: "1.15rem",
              fontWeight: "600",
              lineHeight: "1.6",
              color: "#333",
              margin: 0,
            }}
          >
            {DCS_QUESTIONS[currentDcsIndex].text}
          </p>
        </div>

        {/* 答案選項區 */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "12px",
            width: "100%",
            marginBottom: "20px",
          }}
        >
          {DCS_OPTIONS.map((opt) => (
            <button
              key={opt.value}
              onClick={() => handleDcsSelect(opt.value)}
              style={dcsOptionButtonStyle}
            >
              {opt.label}
            </button>
          ))}
        </div>

        {/* 返回上一題 */}
        {currentDcsIndex > 0 && (
          <button
            onClick={() => setCurrentDcsIndex(currentDcsIndex - 1)}
            style={backQuestionButtonStyle}
          >
            ← 返回上一題
          </button>
        )}
      </div>
    </div>
  );
};

// 🎯 關鍵樣式：改用 absolute 定位，牢牢鎖在父容器（手機框）裡面
const containerBoundedOverlayStyle = {
  position: "absolute",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "#fcf8f9", // 與主頁底色融合的溫柔粉白
  zIndex: 100, // 確保覆蓋住內文，但不會跑出手機框外
  display: "flex",
  justifyContent: "center",
  alignItems: "start",
  boxSizing: "border-box",
};

const contentStyle = {
  width: "100%",
  height: "100%",
  padding: "20px 24px",
  display: "flex",
  flexDirection: "column",
  alignItems: "center",
  justifyContent: "start",
  boxSizing: "border-box",
  overflowY: "auto", // 避免小螢幕手機題目塞不下
};

const citationHeaderStyle = {
  textAlign: "center",
  borderBottom: "1px solid #f5efe3",
  paddingBottom: "10px",
  marginBottom: "20px",
  width: "100%",
  color: "#bc7996",
};
const progressContainerStyle = {
  width: "100%",
  display: "flex",
  alignItems: "center",
  gap: "12px",
  marginBottom: "25px",
};
const progressBarBgStyle = {
  flex: 1,
  height: "6px",
  backgroundColor: "#f0f0f0",
  borderRadius: "3px",
  overflow: "hidden",
};
const progressFillStyle = {
  height: "100%",
  backgroundColor: "#e89abe",
  borderRadius: "3px",
  transition: "width 0.3s ease",
};
const questionZoneStyle = {
  flex: 1,
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  textAlign: "center",
  padding: "10px 0",
  marginBottom: "20px",
};
const dcsOptionButtonStyle = {
  width: "100%",
  padding: "14px",
  backgroundColor: "#fff",
  border: "1.5px solid #f0e2e7",
  borderRadius: "14px",
  fontSize: "1rem",
  fontWeight: "500",
  color: "#4a4a4a",
  cursor: "pointer",
  transition: "all 0.15s",
  textAlign: "center",
  boxShadow: "0 2px 6px rgba(0,0,0,0.01)",
};
const backQuestionButtonStyle = {
  background: "none",
  border: "none",
  color: "#a0a0a0",
  cursor: "pointer",
  textDecoration: "underline",
  fontSize: "0.9rem",
  marginTop: "5px",
};

export default DcsSurvey;
